/* ---------- helpers ---------- */

static string trim(const string &s)
{
	size_t b = s.find_first_not_of(" \t\r\n");
	if (b == string::npos) return "";
	size_t e = s.find_last_not_of(" \t\r\n");
	return s.substr(b, e - b + 1);
}

// split on a top-level (paren-depth 0) single-character delimiter
static vector<string> splitTop(const string &s, char delim)
{
	vector<string> out;
	int depth = 0; size_t start = 0;
	for (size_t i = 0; i < s.size(); i++) {
		if (s[i] == '(' || s[i] == '[') depth++;
		else if (s[i] == ')' || s[i] == ']') depth--;
		else if (s[i] == delim && depth == 0) { out.push_back(trim(s.substr(start, i - start))); start = i + 1; }
	}
	out.push_back(trim(s.substr(start)));
	return out;
}

static size_t matchBracket(const string &s, size_t open)
{
	char o = s[open], c = (o == '(' ? ')' : ']');
	int depth = 0;
	for (size_t i = open; i < s.size(); i++) {
		if (s[i] == o) depth++;
		else if (s[i] == c && --depth == 0) return i;
	}
	return string::npos;
}

static size_t findTopJoin(const string &s)
{
	int depth = 0;
	for (size_t i = 0; i + 4 <= s.size(); i++) {
		if (s[i] == '(' || s[i] == '[') depth++;
		else if (s[i] == ')' || s[i] == ']') depth--;
		else if (depth == 0 && s.compare(i, 4, "JOIN") == 0 && i > 0 && s[i-1] == ' ')
			return i;
	}
	return string::npos;
}

static TreeNode *build(string q)
{
	q = trim(q);
	// strip a pair of parentheses that wraps the whole expression
	while (q.size() > 1 && q[0] == '(' && matchBracket(q, 0) == q.size() - 1)
		q = trim(q.substr(1, q.size() - 2));

	if (q.compare(0, 6, "SELECT") == 0 || q.compare(0, 10, "PROJECTION") == 0) {
		string op = (q[0] == 'S') ? "SELECT" : "PROJECTION";
		size_t lb = q.find('['), rb = matchBracket(q, lb);
		string info = trim(q.substr(lb + 1, rb - lb - 1));
		size_t lp = q.find('(', rb), rp = matchBracket(q, lp);
		TreeNode *n = new TreeNode(op, info);
		n->left = build(q.substr(lp + 1, rp - lp - 1));
		return n;
	}
	size_t j = findTopJoin(q);
	if (j != string::npos) {
		TreeNode *n = new TreeNode("JOIN");
		n->left = build(q.substr(0, j));
		n->right = build(q.substr(j + 4));
		return n;
	}
	return new TreeNode("LEAF", q);
}

