static bool has(const vector<string> &v, const string &s)
{
	for (size_t i = 0; i < v.size(); i++) if (v[i] == s) return true;
	return false;
}

// attributes referenced by a predicate: LHS always, RHS only when unquoted
static vector<string> attrsOf(const string &pred)
{
	vector<string> a;
	size_t eq = pred.find_first_of("=<>");
	if (eq == string::npos) { a.push_back(trim(pred)); return a; }
	string lhs = trim(pred.substr(0, eq));
	size_t dot = lhs.find('.');
	a.push_back(dot == string::npos ? lhs : lhs.substr(dot + 1));
	string rhs = trim(pred.substr(pred.find_first_not_of("=<> ", eq)));
	if (!rhs.empty() && rhs[0] != '\'' && !isdigit((unsigned char)rhs[0])) {
		dot = rhs.find('.');
		a.push_back(dot == string::npos ? rhs : rhs.substr(dot + 1));
	}
	return a;
}

// owning relation of a predicate, "" when undecidable
static string ownerOf(const string &pred, const vector<string> &cand)
{
	size_t eq = pred.find_first_of("=<>");
	string lhs = trim(eq == string::npos ? pred : pred.substr(0, eq));
	size_t dot = lhs.find('.');
	if (dot != string::npos) {                        // (2) qualified prefix
		string q = lhs.substr(0, dot);
		if (has(cand, q)) return q;
	}
	string attr = (dot == string::npos ? lhs : lhs.substr(dot + 1));
	for (int i = 0; CATALOG[i][0]; i++)               // (1) catalog
		if (attr == CATALOG[i][0] && has(cand, CATALOG[i][1])) return CATALOG[i][1];
	for (size_t i = 0; i < cand.size(); i++)          // (3) first-letter
		if (!attr.empty() && !cand[i].empty() && attr[0] == cand[i][0]) return cand[i];
	return "";
}

static TreeNode *wrapSelect(TreeNode *child, const vector<string> &preds)
{
	if (preds.empty()) return child;
	string info = preds[0];
	for (size_t i = 1; i < preds.size(); i++) info += " & " + preds[i];
	TreeNode *s = new TreeNode("SELECT", info);
	s->left = child;
	return s;
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	if (root == NULL) return NULL;

	if (root->type == "SELECT") {
		vector<string> parts = splitTop(root->info, '&');
		for (size_t i = 0; i < parts.size(); i++)
			if (!parts[i].empty()) info.push_back(parts[i]);
		return optimizeQuery(root->left, info);       // node dissolved
	}

	if (root->type == "PROJECTION") {
		vector<string> keepList = splitTop(root->info, ','), down, stay;
		for (size_t i = 0; i < info.size(); i++) {    // push through only if attrs survive
			vector<string> a = attrsOf(info[i]);
			bool ok = true;
			for (size_t k = 0; k < a.size(); k++) if (!has(keepList, a[k])) ok = false;
			(ok ? down : stay).push_back(info[i]);
		}
		root->left = optimizeQuery(root->left, down);
		return wrapSelect(root, stay);
	}

	if (root->type == "JOIN") {
		vector<string> lrel, rrel; collectLeaves(root->left, lrel); collectLeaves(root->right, rrel);
		vector<string> lp, rp, keep;
		int nextSide = 0;                             // (4) positional fallback cursor
		for (size_t i = 0; i < info.size(); i++) {
			string ownL = ownerOf(info[i], lrel), ownR = ownerOf(info[i], rrel);
			if (!ownL.empty() && ownR.empty()) lp.push_back(info[i]);
			else if (ownL.empty() && !ownR.empty()) rp.push_back(info[i]);
			else if (!ownL.empty() && !ownR.empty()) keep.push_back(info[i]);   // (5) join cond
			else { (nextSide == 0 ? lp : rp).push_back(info[i]); nextSide ^= 1; }
		}
		root->left = optimizeQuery(root->left, lp);
		root->right = optimizeQuery(root->right, rp);
		return wrapSelect(root, keep);
	}

	return wrapSelect(root, info);                    // LEAF
}
