	if (q.compare(0, 6, "SELECT") == 0 || q.compare(0, 10, "PROJECTION") == 0) {
		string op = (q[0] == 'S') ? "SELECT" : "PROJECTION";
		size_t lb = q.find('['), rb = matchBracket(q, lb);
		TreeNode *n = new TreeNode(op, trim(q.substr(lb + 1, rb - lb - 1)));
		size_t lp = q.find('(', rb), rp = matchBracket(q, lp);
		n->left = build(q.substr(lp + 1, rp - lp - 1));
		return n;
	}
	size_t j = findTopJoin(q);
	if (j != string::npos) {
		TreeNode *n = new TreeNode("JOIN");
		n->left = build(q.substr(0, j));
		n->right = build(q.substr(j + 4));
		return n;
	}
	return new TreeNode("LEAF", q);
}

void parseQuery(TreeNode *root, string query) { root->left = build(query); }

static const char *CATALOG[][2] = {
	{"ENAME","EMPLOYEE"},{"FNAME","EMPLOYEE"},{"MINIT","EMPLOYEE"},{"LNAME","EMPLOYEE"},
	{"SSN","EMPLOYEE"},{"BDATE","EMPLOYEE"},{"ADDRESS","EMPLOYEE"},{"SEX","EMPLOYEE"},
