static void collectLeaves(TreeNode *n, vector<string> &rels)
{
	if (n == NULL) return;
	if (n->type == "LEAF") rels.push_back(n->info);
	collectLeaves(n->left, rels); collectLeaves(n->right, rels);
}
static bool has(const vector<string> &v, const string &s)
{ for (size_t i = 0; i < v.size(); i++) if (v[i] == s) return true; return false; }

static vector<string> attrsOf(const string &pred)
{
	vector<string> a; size_t eq = pred.find_first_of("=<>!");
	if (eq == string::npos) { a.push_back(trim(pred)); return a; }
	a.push_back(trim(pred.substr(0, eq)));
	size_t rs = pred.find_first_not_of("=<>! ", eq);
	if (rs != string::npos) {
		string rhs = trim(pred.substr(rs));
		if (!rhs.empty() && rhs[0] != '\'' && !isdigit((unsigned char)rhs[0])) a.push_back(rhs);
	}
	return a;
}

// (1) catalog, (2) qualified prefix, (3) first-letter; "" = undecidable
static string ownerOf(string attr, const vector<string> &cand)
{
	size_t dot = attr.find('.');
	if (dot != string::npos) { string q = attr.substr(0, dot); if (has(cand, q)) return q; attr = attr.substr(dot + 1); }
	for (int i = 0; CATALOG[i][0]; i++)
		if (attr == CATALOG[i][0] && has(cand, CATALOG[i][1])) return CATALOG[i][1];
	for (size_t i = 0; i < cand.size(); i++)
		if (!attr.empty() && !cand[i].empty() && attr[0] == cand[i][0]) return cand[i];
	return "";
}

static TreeNode *wrapSelect(TreeNode *child, const vector<string> &preds)
{
	if (preds.empty()) return child;
	string info = preds[0];
	for (size_t i = 1; i < preds.size(); i++) info += " & " + preds[i];
	TreeNode *s = new TreeNode("SELECT", info);
	s->left = child;
	return s;
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	if (root == NULL) return NULL;
	if (root->type == "SELECT") {
		vector<string> parts = splitTop(root->info, '&');
		for (size_t i = 0; i < parts.size(); i++) if (!parts[i].empty()) info.push_back(parts[i]);
		return optimizeQuery(root->left, info);
	}
	if (root->type == "PROJECTION") {
		vector<string> keepList = splitTop(root->info, ','), down, stay;
		for (size_t i = 0; i < info.size(); i++) {
			vector<string> a = attrsOf(info[i]); bool ok = true;
			for (size_t k = 0; k < a.size(); k++) if (!has(keepList, a[k])) ok = false;
			(ok ? down : stay).push_back(info[i]);
		}
		root->left = optimizeQuery(root->left, down);
		return wrapSelect(root, stay);
	}
	if (root->type == "JOIN") {
		vector<string> lrel, rrel, lp, rp, keep;
		collectLeaves(root->left, lrel); collectLeaves(root->right, rrel);
		int nextSide = 0;
		for (size_t i = 0; i < info.size(); i++) {
			vector<string> a = attrsOf(info[i]);
			bool touchL = false, touchR = false, unknown = false;
			for (size_t k = 0; k < a.size(); k++) {
				string o = ownerOf(a[k], lrel), p = ownerOf(a[k], rrel);
				if (!o.empty()) touchL = true;
				if (!p.empty()) touchR = true;
				if (o.empty() && p.empty()) unknown = true;
			}
			if (touchL && touchR) keep.push_back(info[i]);
			else if (touchL && !unknown) lp.push_back(info[i]);
			else if (touchR && !unknown) rp.push_back(info[i]);
			else { (nextSide == 0 ? lp : rp).push_back(info[i]); nextSide ^= 1; }
		}
		root->left = optimizeQuery(root->left, lp);
		root->right = optimizeQuery(root->right, rp);
		return wrapSelect(root, keep);
	}
	return wrapSelect(root, info); // LEAF
}
